import { type EditPost } from '@divi/types';
/**
 * Removes attributes in a module.
 *
 * This action removes one or more specific attributes from a module.
 *
 * When identifying an attribute to be removed, nested attribute names can be targeted
 * by using dot notation. For example:
 * - If the passed attribute name is "content", the entire `content` attribute will be
 * removed.
 * - If the passed attribute name is "content.text", only the text attribute (and its
 * children) will be removed from `content`, and any other attributes within will be
 * left unchanged.
 * - If the passed attribute name is "content.text.desktop", only the `desktop`
 * attribute within `content.text` will be removed. The rest of `content` will be left
 * unchanged.
 *
 * @since ??
 * @group Dispatch Functions
 * @remarks Data Store Dispatch Function
 *
 * @example
 * ```ts
 * window.divi.data.dispatch('divi/edit-post').removeModuleAttribute('module123', 'content', 'global-layout');
 */
export declare const removeModuleAttribute: (id: string, attrName: string, caller?: EditPost.Store.Caller) => EditPost.Store.Actions.RemoveModuleAttribute.ReturnValue;
